"""Base class and result models for evaluators."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Dict
from pydantic import BaseModel, ConfigDict, Field
from exetasiz.core.models import TestCase


class EvaluatorOutput(BaseModel):
    """Output generated by an evaluator for a single test case evaluation."""

    model_config = ConfigDict(extra="forbid")

    score: float = Field(..., ge=0.0, le=1.0, description="Evaluation score from 0.0 to 1.0")
    passed: bool = Field(..., description="Whether the test passed based on evaluator logic")
    details: Dict[str, Any] = Field(default_factory=dict, description="Diagnostic details or explanations")


class Evaluator(ABC):
    """Abstract base class for all evaluators."""

    name: str

    def __init__(self, name: str) -> None:
        self.name = name

    @abstractmethod
    def evaluate(self, test_case: TestCase, generated_answer: str) -> EvaluatorOutput:
        """Evaluates a generated answer against the given test case.

        Args:
            test_case: Ground truth TestCase instance.
            generated_answer: Model output string to evaluate.

        Returns:
            EvaluatorOutput with score, passed flag, and details.
        """
        ...
